const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const crypto = require('crypto');

const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);
const mkdir = promisify(fs.mkdir);

const CHUNK_SIZE = 65536;
const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB
const UPLOAD_DIR = path.join(__dirname, 'uploads');

class ChunkAssembler {
  constructor() {
    this.sessions = new Map();
    this.gcInterval = setInterval(() => this._gc(), 60000);
  }

  async initSession(sessionId, totalChunks, expectedSize) {
    if (expectedSize > MAX_FILE_SIZE) {
      throw new Error('File too large');
    }
    const session = {
      id: sessionId,
      totalChunks: totalChunks,
      expectedSize: expectedSize,
      receivedChunks: new Map(),
      assembledSize: 0,
      createdAt: Date.now(),
      finalized: false
    };
    this.sessions.set(sessionId, session);
    return session;
  }

  async addChunk(sessionId, chunkIndex, data) {
    const session = this.sessions.get(sessionId);
    if (!session) throw new Error('Invalid session');
    if (session.finalized) throw new Error('Session already finalized');
    if (chunkIndex < 0 || chunkIndex >= session.totalChunks) {
      throw new Error('Invalid chunk index');
    }
    if (data.length > CHUNK_SIZE) {
      throw new Error('Chunk exceeds maximum size');
    }
    session.receivedChunks.set(chunkIndex, data);
    session.assembledSize = this._calculateAssembledSize(session);
    // Enforce the absolute maximum file size against the actual accumulated
    // data, not just the client-declared expectedSize.
    if (session.assembledSize > MAX_FILE_SIZE) {
      session.receivedChunks.delete(chunkIndex);
      session.assembledSize = this._calculateAssembledSize(session);
      throw new Error('Assembled data exceeds maximum file size');
    }
    return { received: session.receivedChunks.size, total: session.totalChunks };
  }

  _calculateAssembledSize(session) {
    let size = 0;
    for (const [, chunk] of session.receivedChunks) {
      size += chunk.length;
    }
    return size;
  }

  async finalizeSession(sessionId) {
    const session = this.sessions.get(sessionId);
    if (!session) throw new Error('Invalid session');
    if (session.receivedChunks.size !== session.totalChunks) {
      throw new Error('Missing chunks');
    }
    session.finalized = true;
    const outputBuffer = this._assembleChunks(session);
    const hash = crypto.createHash('sha256').update(outputBuffer).digest('hex');
    const outputPath = path.join(UPLOAD_DIR, `${hash}.bin`);
    await mkdir(UPLOAD_DIR, { recursive: true });
    await writeFile(outputPath, outputBuffer);
    this.sessions.delete(sessionId);
    return { path: outputPath, size: outputBuffer.length, hash };
  }

  _assembleChunks(session) {
    // Calculate actual size from received chunks
    const actualSize = this._calculateAssembledSize(session);
    const outputBuffer = Buffer.allocUnsafe(actualSize);
    let offset = 0;
    for (let i = 0; i < session.totalChunks; i++) {
      const chunk = session.receivedChunks.get(i);
      chunk.copy(outputBuffer, offset);
      offset += chunk.length;
    }
    return outputBuffer;
  }

  _gc() {
    const now = Date.now();
    for (const [id, session] of this.sessions) {
      if (now - session.createdAt > 300000) {
        this.sessions.delete(id);
      }
    }
  }

  destroy() {
    clearInterval(this.gcInterval);
  }
}

class FileProcessingService {
  constructor() {
    this.assembler = new ChunkAssembler();
    this.processingQueue = [];
    this.concurrency = 4;
    this.activeWorkers = 0;
  }

  async handleUploadInit(req) {
    const { sessionId, totalChunks, fileSize } = req.body;
    if (!sessionId || !totalChunks || !fileSize) {
      throw new Error('Missing required fields');
    }
    if (typeof totalChunks !== 'number' || totalChunks <= 0 || totalChunks > 1000) {
      throw new Error('Invalid totalChunks');
    }
    if (typeof fileSize !== 'number' || fileSize <= 0) {
      throw new Error('Invalid fileSize');
    }
    return this.assembler.initSession(sessionId, totalChunks, fileSize);
  }

  async handleChunkUpload(req) {
    const { sessionId, chunkIndex } = req.body;
    const data = req.body.data;
    if (typeof chunkIndex !== 'number' || !Number.isInteger(chunkIndex)) {
      throw new Error('Invalid chunkIndex');
    }
    if (!Buffer.isBuffer(data)) {
      throw new Error('Data must be a buffer');
    }
    return this.assembler.addChunk(sessionId, chunkIndex, data);
  }

  async handleFinalize(req) {
    const { sessionId } = req.body;
    const result = await this.assembler.finalizeSession(sessionId);
    this._enqueueProcessing(result.path);
    return result;
  }

  _enqueueProcessing(filePath) {
    this.processingQueue.push(filePath);
    this._processNext();
  }

  async _processNext() {
    if (this.activeWorkers >= this.concurrency) return;
    if (this.processingQueue.length === 0) return;
    this.activeWorkers++;
    const filePath = this.processingQueue.shift();
    try {
      await this._processFile(filePath);
    } catch (e) {
      console.error('Processing error:', e.message);
    } finally {
      this.activeWorkers--;
      this._processNext();
    }
  }

  async _processFile(filePath) {
    const data = await readFile(filePath);
    // Simulate processing
    const result = {
      size: data.length,
      hash: crypto.createHash('sha256').update(data).digest('hex'),
      processedAt: new Date().toISOString()
    };
    const metaPath = filePath.replace('.bin', '.meta.json');
    await writeFile(metaPath, JSON.stringify(result, null, 2));
    return result;
  }
}

module.exports = { FileProcessingService, ChunkAssembler };
